/* Replace work.reg_train with your SAS libref/table when running externally. */

proc contents data=work.reg_train;
run;

proc means data=work.reg_train n mean median std min max;
    var MedInc HouseAge AveRooms AveBedrms Population AveOccup Latitude Longitude MedHouseVal;
run;

proc corr data=work.reg_train;
    var MedInc HouseAge AveRooms AveBedrms Population AveOccup Latitude Longitude MedHouseVal;
run;

proc sgplot data=work.reg_train;
    histogram MedInc;
    density MedInc;
run;

/* Pivot-style summary */
proc rank data=work.reg_train groups=5 out=work.reg_train_binned;
    var MedInc;
    ranks MedInc_band;
run;

proc means data=work.reg_train_binned n mean median std;
    class MedInc_band;
    var MedInc;
run;

